        :root{--primary:#075985;--ink:#172033;--muted:#64748b;--line:#dbe4ee;--ok:#166534;--warn:#92400e;--bad:#991b1b}*{box-sizing:border-box}body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif;background:#eef4f8;color:var(--ink)}main{max-width:760px;margin:auto;padding:calc(16px + env(safe-area-inset-top)) 14px calc(28px + env(safe-area-inset-bottom))}.topbar,.statusbar,.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.topbar{justify-content:space-between;margin-bottom:14px}h1{font-size:clamp(1.35rem,5vw,1.8rem);margin:0}h2{font-size:1.05rem;margin:0 0 10px}.card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:18px;box-shadow:0 10px 30px #0f172a0d;margin-bottom:14px}.sub,.hint{color:var(--muted)}.sub{margin:5px 0 0}.hint{font-size:.87rem;margin:7px 0 0}.chip{border-radius:999px;padding:7px 10px;font-size:.82rem;font-weight:700;background:#e2e8f0}.chip.online{color:var(--ok);background:#dcfce7}.chip.offline{color:var(--bad);background:#fee2e2}.chip.queue{color:var(--warn);background:#fef3c7}label{display:block;font-weight:700;margin:14px 0 6px}input,select,textarea,button,a.button{width:100%;border:1px solid #cbd5e1;border-radius:11px;padding:12px;font:inherit;background:#fff;color:var(--ink)}input:focus,select:focus,textarea:focus{outline:3px solid #38bdf840;border-color:#0891b2}textarea{min-height:76px;resize:vertical}button,a.button{border:0;background:var(--primary);color:#fff;font-weight:750;cursor:pointer;text-align:center;text-decoration:none}button.secondary,a.button.secondary{width:auto;background:#e2e8f0;color:#1e293b}button.ghost{width:auto;background:#fff;color:var(--primary);border:1px solid #bae6fd}button:disabled{opacity:.55;cursor:not-allowed}.camera{position:relative;overflow:hidden;border-radius:14px;background:#0f172a;aspect-ratio:4/3;display:none;margin-top:12px}.camera.active{display:block}video{width:100%;height:100%;object-fit:cover}.finder{position:absolute;inset:20%;border:3px solid #fbbf24;border-radius:16px;box-shadow:0 0 0 999px #0005}.notice{padding:12px;border-radius:10px;margin:0 0 12px}.ok{background:#dcfce7;color:var(--ok)}.error{background:#fee2e2;color:var(--bad)}#messages{display:grid;gap:8px;margin-top:12px}.message{padding:10px 12px;border-radius:10px;background:#f8fafc;border:1px solid var(--line);font-size:.9rem}.file-label{display:block;text-align:center;border:1px dashed #94a3b8;border-radius:11px;padding:11px;color:#334155;cursor:pointer}.file-label input{display:none}@media(min-width:620px){.grid{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}.actions>*{flex:1}}
    </style>
