            <div class="grid"><div><label for="result">Αποτέλεσμα</label><select id="result" name="result"><option value="found">Βρέθηκε</option><option value="wrong_location">Λάθος τοποθεσία</option><option value="damaged">Κατεστραμμένο</option></select></div><div><label for="actual_location_id">Πραγματική τοποθεσία</label><select id="actual_location_id" name="actual_location_id"><option value="">Ίδια με την καταχωρισμένη</option>@foreach($locations as $location)<option value="{{ $location->id }}">{{ $location->name }}</option>@endforeach</select></div></div>
