</main>
<script>
(()=>{
const userId=@json(auth()->id()),cycleId=@json($cycle->id),syncUrl=@json(route('inventory.scan.sync',$cycle)),queueKey=`assetRegistryInventoryQueue:v1:${userId}:${cycleId}`,token=document.querySelector('meta[name="csrf-token"]').content;
const form=document.getElementById('scanForm'),codeInput=document.getElementById('asset_code'),messages=document.getElementById('messages'),connectionStatus=document.getElementById('connectionStatus'),queueStatus=document.getElementById('queueStatus'),syncButton=document.getElementById('syncButton'),cameraButton=document.getElementById('cameraButton'),stopCameraButton=document.getElementById('stopCameraButton'),camera=document.getElementById('camera'),video=document.getElementById('video');
let stream=null,scanning=false,syncing=false,lastCode='',lastScanAt=0,installPrompt=null;
const queue=()=>{try{return JSON.parse(localStorage.getItem(queueKey)||'[]')}catch(_){return[]}},saveQueue=items=>{localStorage.setItem(queueKey,JSON.stringify(items));renderStatus()},makeId=()=>self.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
const addMessage=(text,kind='')=>{const el=document.createElement('div');el.className=`message ${kind}`;el.textContent=text;messages.prepend(el);while(messages.children.length>5)messages.lastElementChild.remove()};
function renderStatus(){connectionStatus.textContent=navigator.onLine?'Συνδεδεμένο':'Χωρίς σύνδεση';connectionStatus.className=`chip ${navigator.onLine?'online':'offline'}`;queueStatus.textContent=`Σε αναμονή: ${queue().length}`;syncButton.disabled=!navigator.onLine||queue().length===0||syncing}
async function syncQueue(){const items=queue();if(!navigator.onLine||!items.length||syncing)return;syncing=true;renderStatus();try{const response=await fetch(syncUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':token},body:JSON.stringify({items})}),data=await response.json();if(!response.ok)throw new Error(data.message||'Ο συγχρονισμός απέτυχε.');const completed=new Set([...(data.accepted||[]),...(data.rejected||[])].map(item=>item.client_id));saveQueue(items.filter(item=>!completed.has(item.client_id)));(data.accepted||[]).forEach(item=>addMessage(`✓ ${item.asset_code} — ${item.asset_name}`,'ok'));(data.rejected||[]).forEach(item=>addMessage(`Δεν καταχωρίστηκε: ${item.message}`,'error'))}catch(error){addMessage(navigator.onLine?error.message:'Οι σαρώσεις παραμένουν στη συσκευή μέχρι να επανέλθει η σύνδεση.','error')}finally{syncing=false;renderStatus()}}
form.addEventListener('submit',async event=>{event.preventDefault();const code=codeInput.value.trim();if(!code)return codeInput.focus();const items=queue();items.push({client_id:makeId(),asset_code:code,result:document.getElementById('result').value,actual_location_id:document.getElementById('actual_location_id').value||null,notes:document.getElementById('notes').value.trim()||null});saveQueue(items);addMessage(`Η σάρωση ${code} αποθηκεύτηκε ${navigator.onLine?'και αναμένει συγχρονισμό.':'προσωρινά στη συσκευή.'}`);codeInput.value='';document.getElementById('notes').value='';codeInput.focus();await syncQueue()});
async function stopCamera(){scanning=false;stream?.getTracks().forEach(track=>track.stop());stream=null;video.srcObject=null;camera.classList.remove('active');cameraButton.hidden=false;stopCameraButton.hidden=true}
async function detectLoop(detector){if(!scanning)return;try{const codes=await detector.detect(video);if(codes[0]){const value=codes[0].rawValue.trim(),now=Date.now();if(value&&(value!==lastCode||now-lastScanAt>3000)){lastCode=value;lastScanAt=now;codeInput.value=value;navigator.vibrate?.(120);addMessage(`Αναγνώστηκε ο κωδικός ${value}.`);await stopCamera();codeInput.focus();return}}}catch(_){}requestAnimationFrame(()=>detectLoop(detector))}
cameraButton.addEventListener('click',async()=>{if(!('BarcodeDetector'in window)||!navigator.mediaDevices?.getUserMedia){addMessage('Η συσκευή δεν υποστηρίζει ζωντανή ανάγνωση QR. Χρησιμοποιήστε φωτογραφία ή πληκτρολόγηση.','error');return}try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});video.srcObject=stream;await video.play();camera.classList.add('active');cameraButton.hidden=true;stopCameraButton.hidden=false;scanning=true;detectLoop(new BarcodeDetector({formats:['qr_code']}))}catch(_){addMessage('Δεν ήταν δυνατή η πρόσβαση στην κάμερα. Ελέγξτε την άδεια της συσκευής.','error')}});stopCameraButton.addEventListener('click',stopCamera);
document.getElementById('qr_image').addEventListener('change',async event=>{const file=event.target.files[0];if(!file||!('BarcodeDetector'in window)){addMessage('Η αυτόματη ανάγνωση φωτογραφίας δεν υποστηρίζεται. Πληκτρολογήστε τον κωδικό.','error');return}try{const codes=await new BarcodeDetector({formats:['qr_code']}).detect(await createImageBitmap(file));if(codes[0]){codeInput.value=codes[0].rawValue;addMessage('Ο κωδικός QR διαβάστηκε από τη φωτογραφία.')}else addMessage('Δεν εντοπίστηκε QR στη φωτογραφία.','error')}catch(_){addMessage('Δεν ήταν δυνατή η ανάγνωση της φωτογραφίας.','error')}});
syncButton.addEventListener('click',syncQueue);window.addEventListener('online',()=>{renderStatus();syncQueue()});window.addEventListener('offline',renderStatus);window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;document.getElementById('installButton').hidden=false});document.getElementById('installButton').addEventListener('click',async event=>{if(!installPrompt)return;installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;event.currentTarget.hidden=true});if(!window.isSecureContext&&location.hostname!=='localhost')addMessage('Για χρήση κάμερας και εγκατάσταση ως εφαρμογή, ανοίξτε το Μητρώο Παγίων μέσω HTTPS.','error');navigator.serviceWorker?.register('/service-worker.js').catch(()=>{});renderStatus();syncQueue();
})();
</script>@include('filament.partials.contextual-help')</body></html>
